"use client";

import {
  type FC,
  type ReactNode,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
/**
 * `<SlideDeck>` — composite engine orchestrating N `<Slide>` primitives.
 *
 * Subpath-isolated at `@theokit/ui/slide-deck` (ADR D1). Imports `<Slide>` via
 * the public package path so consumer's installed peer-deps are reused.
 *
 * See RFC 0003 and the plan in
 * `wiki/rfcs/0003-slide-deck.md`.
 *
 * Two render modes:
 *   - DEFAULT layout: no children → renders canonical chrome (Slides + Controls
 *     + ProgressBar + SlideNumber + PresenterView + buttons).
 *   - HEADLESS: children provided → consumer composes own layout from
 *     `<SlideDeck.X>` sub-components and a shared DeckContext.
 *
 * SSR-safe: parses markdown only inside `useEffect`. Hash routing uses lazy
 * `initFromHash` (D17) to avoid hydration mismatch. Reducer clamps
 * `currentIndex` whenever `slides.length` changes (EC-4 reconciliation).
 */
import { Slide, type SlidePlugin, type SlideProps } from "@/components/ui/slide/index";
import { DeckContext, type DeckContextValue, useDeckContext } from "@/components/blocks/slide-deck/context";
import { Controls } from "@/components/blocks/slide-deck/controls";
import { countFragmentsInMarkdown } from "@/components/blocks/slide-deck/fragments";
import { PresenterView } from "@/components/blocks/slide-deck/presenter-view";
import { printDeck } from "@/components/blocks/slide-deck/print-styles";
import { ProgressBar } from "@/components/blocks/slide-deck/progress-bar";
import type { SlideDeckInput, SlideDeckSlide, SlideDeckTransition } from "@/components/blocks/slide-deck/schema";
import { SlideNumber } from "@/components/blocks/slide-deck/slide-number";
import { splitDeck } from "@/components/blocks/slide-deck/split-deck";
import { Thumbnails } from "@/components/blocks/slide-deck/thumbnails";
import { readInitialHash, useDeckHashRouting } from "@/components/blocks/slide-deck/use-deck-hash-routing";
import { useDeckKeyboard } from "@/components/blocks/slide-deck/use-deck-keyboard";
import { useDeckState } from "@/components/blocks/slide-deck/use-deck-state";
import { useDeckSwipe } from "@/components/blocks/slide-deck/use-deck-swipe";
import { useFullscreen } from "@/components/blocks/slide-deck/use-fullscreen";

import "./transitions.css";

export interface SlideDeckProps {
  /** Markdown string (auto-split) or pre-parsed slide array. */
  slides: SlideDeckInput;
  /** Initial slide index (0-based). Default 0. */
  initialIndex?: number;
  /** Transition preset. Default "fade". */
  transition?: SlideDeckTransition;
  /** Enable keyboard navigation. Default true. */
  enableKeyboard?: boolean;
  /** Enable touch/pointer swipe navigation. Default true. */
  enableTouch?: boolean;
  /** Enable hash routing (#/N). Default true. */
  enableHashRouting?: boolean;
  /** Optional unique deck id (auto-generated UUID if absent). */
  deckId?: string;
  /** Called after each navigation. */
  onIndexChange?: (index: number, slide: SlideDeckSlide | undefined) => void;
  /** Headless mode: render custom chrome using `<SlideDeck.X>` sub-components. */
  children?: ReactNode;
  /** Outer className for the deck root. */
  className?: string;
  /** Accessible label for the deck region. Defaults to "Slide deck". */
  "aria-label"?: string;
  /**
   * Rich-content plugins relayed to every inner `<Slide>` (D15 / RFC 0004).
   * Pass MEMOIZED arrays to avoid re-parses on every render.
   */
  plugins?: SlidePlugin[];
  /**
   * Markdown component overrides relayed to every inner `<Slide>` (B-286).
   *
   * The primitive treats this map as a REPLACEMENT and never as a merge, so a consumer supplying
   * `{ a: MyLink }` also gives up this package's own `img` renderer and the `loading="lazy"`,
   * `decoding="async"` and `alt` normalisation it applies. Supplying nothing keeps all of them.
   *
   * Pass MEMOIZED maps to avoid re-parses on every render.
   */
  components?: SlideProps["components"];
}

function generateDeckId(): string {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return crypto.randomUUID();
  }
  return `deck-${Math.random().toString(36).slice(2, 10)}`;
}

const SlideDeckBase: FC<SlideDeckProps> = ({
  slides: slidesInput,
  initialIndex = 0,
  transition = "fade",
  enableKeyboard = true,
  enableTouch = true,
  enableHashRouting = true,
  deckId: deckIdProp,
  onIndexChange,
  children,
  className,
  "aria-label": ariaLabel = "Slide deck",
  plugins,
  components,
}) => {
  const generatedId = useId();
  const deckId = deckIdProp ?? generatedId ?? generateDeckId();
  const rootRef = useRef<HTMLDivElement>(null);

  const [parsedSlides, setParsedSlides] = useState<SlideDeckSlide[]>(() => {
    return Array.isArray(slidesInput) ? slidesInput : [];
  });

  // Async parse when string markdown is passed. Re-run when prop changes.
  useEffect(() => {
    if (Array.isArray(slidesInput)) {
      setParsedSlides(slidesInput);
      return;
    }
    let cancelled = false;
    splitDeck(slidesInput).then(
      (result) => {
        if (!cancelled) setParsedSlides(result);
      },
      () => {
        if (!cancelled) setParsedSlides([]);
      },
    );
    return () => {
      cancelled = true;
    };
  }, [slidesInput]);

  const [state, dispatch] = useDeckState({
    initialIndex,
    totalSlides: parsedSlides.length,
    initFromHash: enableHashRouting ? readInitialHash : undefined,
  });

  // EC-4: reconcile when slides.length changes.
  const previousLengthRef = useRef(0);
  useEffect(() => {
    const length = parsedSlides.length;
    dispatch({ type: "UPDATE_TOTAL_SLIDES", total: length });
    // First non-empty parse → honour `initialIndex` (or hash) which was clamped
    // to 0 during initial mount when totalSlides was still 0.
    if (previousLengthRef.current === 0 && length > 0) {
      let target = initialIndex;
      if (enableHashRouting) {
        const hashIdx = readInitialHash();
        if (typeof hashIdx === "number") target = hashIdx;
      }
      if (target > 0) {
        dispatch({ type: "JUMP_TO", index: target });
      }
    }
    previousLengthRef.current = length;
  }, [parsedSlides.length, dispatch, initialIndex, enableHashRouting]);

  // Update totalFragmentsInCurrent when slide content changes.
  useEffect(() => {
    const current = parsedSlides[state.currentIndex];
    const count = current ? countFragmentsInMarkdown(current.markdown) : 0;
    dispatch({ type: "UPDATE_TOTAL_FRAGMENTS", total: count });
  }, [parsedSlides, state.currentIndex, dispatch]);

  const fullscreen = useFullscreen(rootRef);

  // Sync state.fullscreen with browser API. When user presses Esc on native UI.
  useEffect(() => {
    dispatch({ type: "SET_FULLSCREEN", value: fullscreen.isFullscreen });
  }, [fullscreen.isFullscreen, dispatch]);

  // EC-3 / D16: transition timeout fallback so rapid nav doesn't leave state stuck.
  useEffect(() => {
    if (state.transitionDirection === "none") return;
    const t = setTimeout(() => dispatch({ type: "TRANSITION_END" }), 300);
    return () => clearTimeout(t);
  }, [state.transitionDirection, dispatch]);

  const onPrint = useCallback(() => {
    printDeck();
  }, []);

  useDeckKeyboard(dispatch, {
    enabled: enableKeyboard,
    totalSlides: parsedSlides.length,
    onToggleFullscreen: fullscreen.toggle,
    onPrint,
  });

  useDeckSwipe(rootRef, dispatch, { enabled: enableTouch });

  useDeckHashRouting(dispatch, {
    enabled: enableHashRouting,
    totalSlides: parsedSlides.length,
    currentIndex: state.currentIndex,
  });

  // Fire onIndexChange callback when currentIndex changes.
  const lastIndexRef = useRef(state.currentIndex);
  useEffect(() => {
    if (lastIndexRef.current !== state.currentIndex) {
      lastIndexRef.current = state.currentIndex;
      onIndexChange?.(state.currentIndex, parsedSlides[state.currentIndex]);
    }
  }, [state.currentIndex, parsedSlides, onIndexChange]);

  const contextValue: DeckContextValue = useMemo(
    () => ({
      state,
      dispatch,
      slides: parsedSlides,
      transition,
      deckId,
      plugins,
      components,
      toggleFullscreen: fullscreen.toggle,
      print: onPrint,
    }),
    [
      state,
      dispatch,
      parsedSlides,
      transition,
      deckId,
      plugins,
      components,
      fullscreen.toggle,
      onPrint,
    ],
  );

  return (
    <DeckContext.Provider data-slot="slide-deck-base" value={contextValue}>
      <div
        ref={rootRef}
        aria-roledescription="slide deck"
        aria-label={ariaLabel}
        data-theo-slide-deck
        data-theo-slide-deck-fullscreen={state.fullscreen ? "true" : undefined}
        className={["theo-slide-deck", className].filter(Boolean).join(" ")}
        style={{ position: "relative", width: "100%", height: "100%" }}
      >
        {/* Live region for screen readers announcing slide changes. */}
        {/* biome-ignore lint/a11y/useSemanticElements: ARIA live region needs explicit role for screen reader announcement; no native HTML equivalent for status updates from non-form, non-output content. */}
        <div
          role="status"
          aria-live="polite"
          aria-atomic="true"
          style={{
            position: "absolute",
            width: 1,
            height: 1,
            padding: 0,
            margin: -1,
            overflow: "hidden",
            clip: "rect(0,0,0,0)",
            whiteSpace: "nowrap",
            border: 0,
          }}
        >
          {parsedSlides.length > 0
            ? `Slide ${state.currentIndex + 1} of ${parsedSlides.length}`
            : "Empty deck"}
        </div>
        {children ?? <DefaultDeckLayout />}
        {/* Hidden print container — visible only during @media print. */}
        <PrintContainer slides={parsedSlides} plugins={plugins} components={components} />
      </div>
    </DeckContext.Provider>
  );
};

const SlidesView: FC<{ className?: string }> = ({ className }) => {
  const { state, slides, transition, plugins, components } = useDeckContext();
  const current = slides[state.currentIndex];
  return (
    <div
      data-slot="slides-view"
      className={["theo-slide-deck-slide-frame", className].filter(Boolean).join(" ")}
      data-theo-slide-deck-transition={transition}
      data-theo-slide-deck-direction={state.transitionDirection}
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        minHeight: 0,
        overflow: "hidden",
      }}
    >
      {current ? (
        <div
          key={state.currentIndex}
          data-theo-slide-deck-slide-state="incoming"
          style={{ position: "absolute", inset: 0 }}
        >
          <Slide
            markdown={current.markdown}
            plugins={plugins}
            components={components}
            aria-label={`Slide ${state.currentIndex + 1}`}
          />
        </div>
      ) : (
        <div
          data-theo-slide-deck-empty
          style={{
            display: "grid",
            placeItems: "center",
            height: "100%",
            opacity: 0.6,
            fontSize: 14,
          }}
        >
          Empty deck
        </div>
      )}
    </div>
  );
};

const PresenterButton: FC<{ className?: string }> = ({ className }) => {
  const { state, dispatch } = useDeckContext();
  return (
    <button
      data-slot="presenter-button"
      type="button"
      onClick={() => dispatch({ type: "TOGGLE_PRESENTER" })}
      aria-pressed={state.presenterMode}
      aria-label={state.presenterMode ? "Close presenter view" : "Open presenter view"}
      className={["theo-slide-deck-presenter-button", className].filter(Boolean).join(" ")}
    >
      {state.presenterMode ? "Close presenter" : "Presenter"}
    </button>
  );
};

const FullscreenButton: FC<{ className?: string }> = ({ className }) => {
  const { state, toggleFullscreen } = useDeckContext();
  return (
    <button
      data-slot="fullscreen-button"
      type="button"
      onClick={() => void toggleFullscreen()}
      aria-pressed={state.fullscreen}
      aria-label={state.fullscreen ? "Exit fullscreen" : "Enter fullscreen"}
      className={["theo-slide-deck-fullscreen-button", className].filter(Boolean).join(" ")}
    >
      {state.fullscreen ? "Exit fullscreen" : "Fullscreen"}
    </button>
  );
};

const PrintButton: FC<{ className?: string }> = ({ className }) => {
  const { print } = useDeckContext();
  return (
    <button
      data-slot="print-button"
      type="button"
      onClick={() => print()}
      aria-label="Print or save deck as PDF"
      className={["theo-slide-deck-print-button", className].filter(Boolean).join(" ")}
    >
      Print
    </button>
  );
};

const PrintContainer: FC<{
  slides: SlideDeckSlide[];
  plugins?: SlidePlugin[];
  /** Drilled rather than read from the context: this component never calls `useDeckContext()`. */
  components?: SlideProps["components"];
}> = ({ slides, plugins, components }) => {
  return (
    <div
      data-slot="print-container"
      className="theo-slide-deck-print-container"
      aria-hidden="true"
      style={{
        position: "absolute",
        inset: 0,
        pointerEvents: "none",
        visibility: "hidden",
      }}
    >
      {slides.map((slide, index) => (
        <div
          key={`print-${slide.id ?? index}`}
          className="theo-slide-deck-print-slide"
          style={{ width: 1280, height: 720 }}
        >
          <Slide
            markdown={slide.markdown}
            plugins={plugins}
            components={components}
            aria-label={`Print slide ${index + 1}`}
          />
        </div>
      ))}
    </div>
  );
};

const DefaultDeckLayout: FC = () => {
  return (
    <div
      data-slot="default-deck-layout"
      className="theo-slide-deck-default-layout"
      style={{
        display: "grid",
        gridTemplateColumns: "1fr",
        gridTemplateRows: "1fr auto",
        gap: 8,
        height: "100%",
      }}
    >
      <SlidesView />
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 8,
          padding: "4px 8px",
          flexWrap: "wrap",
        }}
      >
        <Controls />
        <ProgressBar />
        <div style={{ display: "flex", gap: 4 }}>
          <PresenterButton />
          <FullscreenButton />
          <PrintButton />
        </div>
      </div>
      <SlideNumber />
      <PresenterView />
    </div>
  );
};

type SlideDeckComponent = FC<SlideDeckProps> & {
  Slides: FC<{ className?: string }>;
  Controls: typeof Controls;
  ProgressBar: typeof ProgressBar;
  SlideNumber: typeof SlideNumber;
  Thumbnails: typeof Thumbnails;
  PresenterView: typeof PresenterView;
  PresenterButton: FC<{ className?: string }>;
  FullscreenButton: FC<{ className?: string }>;
  PrintButton: FC<{ className?: string }>;
};

const SlideDeck = SlideDeckBase as SlideDeckComponent;
SlideDeck.Slides = SlidesView;
SlideDeck.Controls = Controls;
SlideDeck.ProgressBar = ProgressBar;
SlideDeck.SlideNumber = SlideNumber;
SlideDeck.Thumbnails = Thumbnails;
SlideDeck.PresenterView = PresenterView;
SlideDeck.PresenterButton = PresenterButton;
SlideDeck.FullscreenButton = FullscreenButton;
SlideDeck.PrintButton = PrintButton;

export { SlideDeck };

"use client";

/**
 * DeckContext — internal Context shared between `<SlideDeck>` and its
 * dot-namespace sub-components (`<SlideDeck.Controls>`, etc.). ADR D14.
 */
import { type Dispatch, createContext, useContext } from "react";
import type { SlidePlugin, SlideProps } from "@/components/ui/slide/index";
import type { SlideDeckSlide, SlideDeckTransition } from "@/components/blocks/slide-deck/schema";
import type { DeckAction, DeckState } from "@/components/blocks/slide-deck/use-deck-state";

export interface DeckContextValue {
  state: DeckState;
  dispatch: Dispatch<DeckAction>;
  slides: SlideDeckSlide[];
  transition: SlideDeckTransition;
  deckId: string;
  /** Rich-content plugins relayed to every inner `<Slide>` (D15). */
  plugins?: SlidePlugin[];
  /**
   * Markdown component overrides relayed to every inner `<Slide>` (B-286).
   * REPLACES the package defaults wholesale rather than merging with them.
   */
  components?: SlideProps["components"];
  /** Toggle browser fullscreen on the deck root. Safe to call when unsupported. */
  toggleFullscreen: () => void | Promise<void>;
  /** Trigger native print dialog with deck-specific @page CSS. */
  print: () => void;
}

export const DeckContext = createContext<DeckContextValue | null>(null);

export function useDeckContext(): DeckContextValue {
  const ctx = useContext(DeckContext);
  if (!ctx) {
    throw new Error(
      "SlideDeck sub-components must be used inside <SlideDeck>. " +
        "Wrap them in <SlideDeck slides={...}>.",
    );
  }
  return ctx;
}

/**
 * `<SlideDeck.Controls>` — prev/next buttons + slide indicator ("3 / 12").
 */
import type { FC } from "react";
import { useDeckContext } from "@/components/blocks/slide-deck/context";

export interface ControlsProps {
  className?: string;
}

export const Controls: FC<ControlsProps> = ({ className }) => {
  const { state, dispatch } = useDeckContext();
  const atStart = state.currentIndex <= 0;
  const atEnd = state.currentIndex >= state.totalSlides - 1;
  return (
    <div
      data-slot="controls"
      className={["theo-slide-deck-controls", className].filter(Boolean).join(" ")}
      data-theo-slide-deck-controls
      style={{
        display: "flex",
        alignItems: "center",
        gap: 8,
      }}
    >
      <button
        type="button"
        aria-label="Previous slide"
        disabled={atStart}
        onClick={() => dispatch({ type: "PREV_SLIDE" })}
        className="theo-slide-deck-controls-prev"
      >
        ←
      </button>
      <span
        aria-live="polite"
        className="theo-slide-deck-controls-indicator"
        style={{ fontVariantNumeric: "tabular-nums", minWidth: 64, textAlign: "center" }}
      >
        {state.totalSlides === 0 ? "0 / 0" : `${state.currentIndex + 1} / ${state.totalSlides}`}
      </span>
      <button
        type="button"
        aria-label="Next slide"
        disabled={atEnd}
        onClick={() => dispatch({ type: "NEXT_SLIDE" })}
        className="theo-slide-deck-controls-next"
      >
        →
      </button>
    </div>
  );
};

/**
 * Progressive fragments detector (ADR D12).
 *
 * Marpit convention: lists with `*` (asterisco) marker — instead of `-` or `+`
 * — become fragment-revealed lists. Each item is a step.
 *
 * Implementation: regex pre-pass on raw markdown counts top-of-line `* ` markers.
 * Decision (EC-9): mixed `*` and `-` in the same list is rare; we count ONLY
 * `* ` items as fragments. Plain `- item` lists remain non-fragmented.
 *
 * v0.4: counts only. CSS attribute application happens at render time inside
 * `<SlideDeck.Slides>`, post-parse, by walking the rendered DOM.
 */

const FRAGMENT_MARKER_RE = /^\s*\*\s+\S/gm;

/**
 * Count fragment markers in raw markdown.
 *
 * Detects only `*` at start of a line followed by space + non-whitespace.
 * Avoids matching `**bold**`, `*italic*`, or `_ * _` patterns.
 */
export function countFragmentsInMarkdown(markdown: string): number {
  if (!markdown) return 0;
  // Strip fenced code blocks first to avoid counting * inside code.
  const stripped = markdown.replace(/```[\s\S]*?```/g, "");
  const matches = stripped.match(FRAGMENT_MARKER_RE);
  return matches ? matches.length : 0;
}

/**
 * Speaker notes extractor (ADR D11).
 *
 * Sintaxe: HTML comments `<!-- notes: ... -->` ou `<!-- note: ... -->`.
 * Aceita ambos singular e plural. Texto interno é plain (sem markdown nesting
 * em v0.4 — pode vir em v0.5).
 *
 * Returns the body with comments removed and the aggregated notes string.
 */

const NOTES_RE = /<!--\s*notes?:\s*([\s\S]*?)\s*-->/gi;

export interface ExtractNotesResult {
  body: string;
  notes: string | undefined;
}

export function extractNotes(md: string): ExtractNotesResult {
  const matches = [...md.matchAll(NOTES_RE)];
  if (matches.length === 0) {
    return { body: md, notes: undefined };
  }
  const notes = matches
    .map((m) => (m[1] ?? "").trim())
    .filter((s) => s.length > 0)
    .join("\n\n");
  const body = md.replace(NOTES_RE, "").trim();
  return { body, notes: notes.length > 0 ? notes : undefined };
}

"use client";

/**
 * `<SlideDeck.PresenterView>` — inline split-screen panel.
 *
 * Pragmatic v0.4 scope: renders an in-page panel (current slide + next slide +
 * speaker notes + timer) when `state.presenterMode === true`. The separate
 * window via `window.open` + `BroadcastChannel` is deferred to v0.5 (consumer
 * demand will trigger the upgrade — D6 of the plan is reduced to inline panel).
 *
 * Toggling presenter mode is dispatched via hotkey (n/N/p/P, see useDeckKeyboard).
 */
import { type FC, useEffect, useRef, useState } from "react";
import { Slide } from "@/components/ui/slide/index";
import { useDeckContext } from "@/components/blocks/slide-deck/context";

export interface PresenterViewProps {
  className?: string;
}

function formatElapsed(ms: number): string {
  const s = Math.floor(ms / 1000);
  const mm = Math.floor(s / 60)
    .toString()
    .padStart(2, "0");
  const ss = (s % 60).toString().padStart(2, "0");
  return `${mm}:${ss}`;
}

export const PresenterView: FC<PresenterViewProps> = ({ className }) => {
  const { state, slides, plugins, components } = useDeckContext();
  const startedAt = useRef<number | null>(null);
  const [elapsed, setElapsed] = useState(0);

  // Initialize the timer when presenter mode first opens; reset when closed.
  useEffect(() => {
    if (state.presenterMode) {
      if (startedAt.current === null) {
        startedAt.current = Date.now();
      }
      const interval = window.setInterval(() => {
        if (startedAt.current !== null) {
          setElapsed(Date.now() - startedAt.current);
        }
      }, 1000);
      return () => window.clearInterval(interval);
    }
    startedAt.current = null;
    setElapsed(0);
    return undefined;
  }, [state.presenterMode]);

  if (!state.presenterMode) return null;

  const current = slides[state.currentIndex];
  const next = slides[state.currentIndex + 1];
  const notes = current?.notes;

  return (
    <aside
      className={["theo-slide-deck-presenter", className].filter(Boolean).join(" ")}
      data-theo-slide-deck-presenter
      aria-label="Presenter view"
      style={{
        display: "grid",
        gridTemplateColumns: "1fr 1fr",
        gridTemplateRows: "auto 1fr",
        gap: 16,
        padding: 16,
        background: "color-mix(in srgb, currentColor 6%, transparent)",
        borderRadius: 8,
      }}
    >
      <header
        style={{
          gridColumn: "1 / -1",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <h3 style={{ margin: 0, fontSize: 14, fontWeight: 600 }}>Presenter view</h3>
        <span
          aria-label="Elapsed time"
          style={{ fontVariantNumeric: "tabular-nums", fontSize: 14 }}
        >
          {formatElapsed(elapsed)}
        </span>
      </header>
      <section aria-label="Current slide preview">
        <h4 style={{ margin: "0 0 8px", fontSize: 12, opacity: 0.7 }}>Current</h4>
        <div
          style={{
            aspectRatio: "16 / 9",
            overflow: "hidden",
            border: "1px solid rgba(127,127,127,0.3)",
            borderRadius: 6,
          }}
        >
          {current ? (
            <Slide
              markdown={current.markdown}
              plugins={plugins}
              components={components}
              aria-label="Current slide"
            />
          ) : null}
        </div>
      </section>
      <section aria-label="Next slide preview">
        <h4 style={{ margin: "0 0 8px", fontSize: 12, opacity: 0.7 }}>Next</h4>
        <div
          style={{
            aspectRatio: "16 / 9",
            overflow: "hidden",
            border: "1px solid rgba(127,127,127,0.3)",
            borderRadius: 6,
            opacity: next ? 1 : 0.4,
          }}
        >
          {next ? (
            <Slide
              markdown={next.markdown}
              plugins={plugins}
              components={components}
              aria-label="Next slide"
            />
          ) : (
            <div style={{ padding: 16, fontSize: 14, opacity: 0.6 }}>End of deck</div>
          )}
        </div>
      </section>
      {notes ? (
        <section
          aria-label="Speaker notes"
          style={{
            gridColumn: "1 / -1",
            background: "color-mix(in srgb, currentColor 8%, transparent)",
            padding: 12,
            borderRadius: 6,
            fontSize: 14,
            whiteSpace: "pre-wrap",
          }}
        >
          <strong>Notes: </strong>
          {notes}
        </section>
      ) : null}
    </aside>
  );
};

/**
 * Print CSS injection (ADR D7).
 *
 * Injects a `<style id="theo-slide-deck-print">` element into the document
 * head with `@page` + `@media print` rules that render `.theo-slide-deck-print-container`
 * with one slide per page. Calls `window.print()`. Removes the style on the
 * `afterprint` event (cleanup runs regardless of print cancel/complete).
 */

const STYLE_ID = "theo-slide-deck-print-styles";
const PRINT_CSS = `
@media print {
  @page {
    size: 1280px 720px;
    margin: 0;
  }
  body > * {
    visibility: hidden;
  }
  .theo-slide-deck-print-container,
  .theo-slide-deck-print-container * {
    visibility: visible;
  }
  .theo-slide-deck-print-container {
    position: absolute;
    inset: 0;
  }
  .theo-slide-deck-print-slide {
    page-break-after: always;
    break-after: page;
    width: 1280px;
    height: 720px;
    overflow: hidden;
  }
  .theo-slide-deck-print-slide:last-child {
    page-break-after: auto;
    break-after: auto;
  }
}
`;

export function injectPrintStyles(): HTMLStyleElement {
  if (typeof document === "undefined") {
    throw new Error("injectPrintStyles requires a document (browser env)");
  }
  let style = document.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!style) {
    style = document.createElement("style");
    style.id = STYLE_ID;
    style.textContent = PRINT_CSS;
    document.head.appendChild(style);
  }
  return style;
}

export function removePrintStyles(): void {
  if (typeof document === "undefined") return;
  const style = document.getElementById(STYLE_ID);
  if (style) style.remove();
}

export interface PrintDeckOptions {
  /** Optional callback fired after print dialog closes (success or cancel). */
  onAfterPrint?: () => void;
}

/**
 * Trigger native print dialog with deck-specific CSS injected.
 *
 * The `afterprint` event listener is cleaned up automatically. Idempotent —
 * calling twice in quick succession is safe (style is reused).
 */
export function printDeck(opts: PrintDeckOptions = {}): void {
  if (typeof window === "undefined" || typeof document === "undefined") return;
  injectPrintStyles();
  const cleanup = (): void => {
    removePrintStyles();
    window.removeEventListener("afterprint", cleanup);
    opts.onAfterPrint?.();
  };
  window.addEventListener("afterprint", cleanup);
  window.print();
}

/**
 * `<SlideDeck.ProgressBar>` — horizontal HTML5 progress element.
 */
import type { FC } from "react";
import { useDeckContext } from "@/components/blocks/slide-deck/context";

export interface ProgressBarProps {
  className?: string;
}

export const ProgressBar: FC<ProgressBarProps> = ({ className }) => {
  const { state } = useDeckContext();
  // Edge case: totalSlides=0 → 0% safely.
  const value = state.totalSlides === 0 ? 0 : state.currentIndex + 1;
  const max = Math.max(1, state.totalSlides);
