/**
 * Zod schema for `<SlideDeck>` input.
 *
 * Two shapes accepted (ADR D4):
 *   - `string` — full markdown, split internally by `splitDeck` (top-level
 *     `thematicBreak`, see ADR D3 / D12 of Slide).
 *   - `SlideDeckSlide[]` — pre-parsed array (CMS/DB consumers).
 *
 * See `wiki/rfcs/0003-slide-deck.md`.
 */
import { z } from "zod";

export const slideDeckSlide = z.object({
  /** Markdown content of this slide. Capped at 50 KB (same as Slide body). */
  markdown: z.string().max(50_000),
  /** Optional id for hash routing (defaults to numeric index, 1-based). */
  id: z
    .string()
    .regex(/^[a-z0-9-]+$/, "id must be lowercase kebab-case")
    .max(64)
    .optional(),
  /** Speaker notes (plain text extracted from <!-- notes: ... --> comments). */
  notes: z.string().max(5_000).optional(),
});

/** Composed input — `slides` prop accepts either form. */
export const slideDeckInput = z.union([z.string().max(500_000), z.array(slideDeckSlide).max(500)]);

export type SlideDeckSlide = z.infer<typeof slideDeckSlide>;
export type SlideDeckInput = z.infer<typeof slideDeckInput>;

/** Transition presets. ADR D8. */
export const slideDeckTransition = z.enum(["none", "fade", "slide"]);
export type SlideDeckTransition = z.infer<typeof slideDeckTransition>;

/**
 * `<SlideDeck.SlideNumber>` — decorative "N / Total" overlay.
 *
 * aria-hidden because the live indicator in <Controls> already announces the
 * current position; this is purely visual chrome.
 */
import type { FC } from "react";
import { useDeckContext } from "@/components/blocks/slide-deck/context";

export interface SlideNumberProps {
  className?: string;
}

export const SlideNumber: FC<SlideNumberProps> = ({ className }) => {
  const { state } = useDeckContext();
  if (state.totalSlides === 0) return null;
  return (
    <div
      className={["theo-slide-deck-slide-number", className].filter(Boolean).join(" ")}
      data-theo-slide-deck-slide-number
      aria-hidden="true"
      style={{
        position: "absolute",
        bottom: 12,
        right: 16,
        fontVariantNumeric: "tabular-nums",
        fontSize: 14,
        opacity: 0.6,
      }}
    >
      {state.currentIndex + 1} / {state.totalSlides}
    </div>
  );
};

/**
 * Split a markdown string into individual slides at top-level `thematicBreak`s.
 *
 * Mirrors the Slide primitive's `detectMultiSlide` algorithm (D12 of RFC 0002),
 * but returns ALL slides instead of truncating.
 *
 * ADR D15: strips global frontmatter FIRST so the leading `---\n...\n---\n`
 * delimiter is not parsed as a `thematicBreak` (which would yield a phantom
 * empty slide #0).
 *
 * The first slide may have its own frontmatter (kept attached); subsequent
 * slides do not parse frontmatter again (consumer's `<Slide markdown>` does
 * per-slide validation).
 */
import { extractFrontmatter } from "@/components/ui/slide/index";
import { extractNotes } from "@/components/blocks/slide-deck/notes";
import type { SlideDeckSlide } from "@/components/blocks/slide-deck/schema";

export async function splitDeck(markdown: string): Promise<SlideDeckSlide[]> {
  // D15: strip leading global frontmatter so its `---` delimiters are not
  // mistaken for slide separators.
  const { body: bodyAfterFM } = extractFrontmatter(markdown);

  if (bodyAfterFM.trim().length === 0) {
    return [];
  }

  const { fromMarkdown } = await import("mdast-util-from-markdown");
  const tree = fromMarkdown(bodyAfterFM);

  const breakOffsets: number[] = [];
  for (const node of tree.children) {
    if (node.type === "thematicBreak") {
      const start = node.position?.start.offset;
      const end = node.position?.end.offset;
      if (typeof start === "number" && typeof end === "number") {
        breakOffsets.push(start);
        breakOffsets.push(end);
      }
    }
  }

  if (breakOffsets.length === 0) {
    // Single-slide deck.
    const { body, notes } = extractNotes(bodyAfterFM);
    if (body.trim().length === 0 && !notes) return [];
    return [{ markdown: body, notes }];
  }

  // Build ranges between (or excluding) the `---` tokens.
  const slides: SlideDeckSlide[] = [];
  const positions: number[] = [0];
  // breakOffsets is [start0, end0, start1, end1, ...]. We want to skip the
  // `---` itself but include the content between them.
  for (let i = 0; i < breakOffsets.length; i += 2) {
    const start = breakOffsets[i];
    const end = breakOffsets[i + 1];
    if (typeof start === "number") positions.push(start);
    if (typeof end === "number") positions.push(end);
  }
  positions.push(bodyAfterFM.length);

  // Pair adjacent positions to form slide ranges (skip the `---` segments).
  for (let i = 0; i < positions.length - 1; i += 2) {
    const start = positions[i];
    const end = positions[i + 1];
    if (typeof start !== "number" || typeof end !== "number") continue;
    const chunk = bodyAfterFM.slice(start, end).trim();
    if (chunk.length === 0) continue;
    const { body, notes } = extractNotes(chunk);
    if (body.trim().length === 0 && !notes) continue;
    slides.push({ markdown: body, notes });
  }

  return slides;
}

"use client";

/**
 * `<SlideDeck.Thumbnails>` — sidebar with mini Slide instances.
 *
 * Performance strategy:
 *   - Each thumbnail renders the actual `<Slide>` inside a scaled wrapper (~0.18×).
 *   - IntersectionObserver lazy-loads thumbnails — off-screen ones show a
 *     placeholder skeleton instead of parsing the markdown.
 *   - EC-13: when IntersectionObserver is undefined (legacy env / SSR), falls
 *     back to eager render. Acceptable for decks ≤ 50 slides.
 *
 * Click handler dispatches JUMP_TO. Auto-scroll keeps current thumbnail visible.
 */
import { type FC, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Slide, type SlidePlugin, type SlideProps } from "@/components/ui/slide/index";
import { useDeckContext } from "@/components/blocks/slide-deck/context";

export interface ThumbnailsProps {
  className?: string;
  /** Scale of each thumbnail. Default 0.18. */
  scale?: number;
}

const CANVAS_W = 1280;
const CANVAS_H = 720;

interface ThumbnailItemProps {
  markdown: string;
  index: number;
  isCurrent: boolean;
  scale: number;
  eager: boolean;
  onSelect: (index: number) => void;
  registerRef: (index: number, el: HTMLElement | null) => void;
  /** Rich-content plugins relayed from DeckContext (D15 / B-288). */
  plugins?: SlidePlugin[];
  /** Markdown component overrides relayed from DeckContext (B-286). */
  components?: SlideProps["components"];
}

const ThumbnailItem: FC<ThumbnailItemProps> = ({
  markdown,
  index,
  isCurrent,
  scale,
  eager,
  onSelect,
  registerRef,
  plugins,
  components,
}) => {
  const [revealed, setRevealed] = useState(eager);

  const setRef = useCallback(
    (el: HTMLElement | null) => {
      registerRef(index, el);
      if (eager) return;
      if (!el) return;
      if (typeof IntersectionObserver === "undefined") {
        // EC-13 fallback: no IO, render eagerly.
        setRevealed(true);
        return;
      }
      const io = new IntersectionObserver(
        (entries) => {
          for (const entry of entries) {
            if (entry.isIntersecting) {
              setRevealed(true);
              io.disconnect();
              break;
            }
          }
        },
        { rootMargin: "200px" },
      );
      io.observe(el);
    },
    [index, eager, registerRef],
  );

  const w = Math.round(CANVAS_W * scale);
  const h = Math.round(CANVAS_H * scale);
  return (
    <button
      data-slot="thumbnail-item"
      ref={setRef}
      type="button"
      onClick={() => onSelect(index)}
      data-theo-slide-deck-thumbnail
      data-current={isCurrent || undefined}
      aria-label={`Slide ${index + 1}`}
      aria-current={isCurrent ? "page" : undefined}
      className="theo-slide-deck-thumbnail"
      style={{
        width: w,
        height: h,
        padding: 0,
        border: isCurrent ? "2px solid currentColor" : "1px solid rgba(127,127,127,0.3)",
        borderRadius: 6,
        overflow: "hidden",
        position: "relative",
        cursor: "pointer",
        flexShrink: 0,
        background: "transparent",
      }}
    >
      <div
        style={{
          width: CANVAS_W,
          height: CANVAS_H,
          transform: `scale(${scale})`,
          transformOrigin: "top left",
          pointerEvents: "none",
        }}
      >
        {revealed ? (
          <Slide
            markdown={markdown}
            plugins={plugins}
            components={components}
            aria-label={`Thumbnail ${index + 1}`}
          />
        ) : (
          <div
            data-theo-slide-deck-thumbnail-placeholder
            style={{
              width: "100%",
              height: "100%",
              background: "rgba(127,127,127,0.08)",
            }}
          />
        )}
      </div>
    </button>
  );
};

export const Thumbnails: FC<ThumbnailsProps> = ({ className, scale = 0.18 }) => {
  const { state, dispatch, slides, plugins, components } = useDeckContext();
  const refs = useRef<Map<number, HTMLElement>>(new Map());

  const registerRef = useCallback((index: number, el: HTMLElement | null) => {
    if (el) {
      refs.current.set(index, el);
    } else {
      refs.current.delete(index);
    }
  }, []);

  const onSelect = useCallback(
    (index: number) => {
      dispatch({ type: "JUMP_TO", index });
    },
    [dispatch],
  );

  // Auto-scroll current into view.
  useEffect(() => {
    const el = refs.current.get(state.currentIndex);
    if (el && "scrollIntoView" in el) {
      el.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "nearest" });
    }
  }, [state.currentIndex]);

  // EC-13: eager mode when IO is absent.
  const eagerAll = useMemo(() => typeof IntersectionObserver === "undefined", []);

  return (
    <ul
      data-slot="thumbnails"
      className={["theo-slide-deck-thumbnails", className].filter(Boolean).join(" ")}
      data-theo-slide-deck-thumbnails
      aria-label="Slide thumbnails"
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 8,
        overflowY: "auto",
        padding: 8,
        listStyle: "none",
        margin: 0,
      }}
    >
      {slides.map((slide, index) => (
        <li key={`${slide.id ?? index}-${index}`}>
          <ThumbnailItem
            markdown={slide.markdown}
            index={index}
            isCurrent={index === state.currentIndex}
            scale={scale}
            eager={eagerAll || index < 3 /* first 3 always eager for snappy first paint */}
            onSelect={onSelect}
            registerRef={registerRef}
            plugins={plugins}
            components={components}
          />
        </li>
      ))}
    </ul>
  );
};

/*
 * Slide deck transitions (ADR D8).
 *
 * Three presets via the `data-theo-slide-deck-transition` attribute on the
 * deck root: "none" | "fade" | "slide".
 *
 * Active transition direction is signaled via `data-theo-slide-deck-direction`
 * ("none" | "next" | "prev"). CSS animations are 250ms, GPU-accelerated.
 *
 * Respects `prefers-reduced-motion: reduce` — all durations collapse to 0ms,
 * effectively becoming "none" regardless of the prop.
 */

.theo-slide-deck-slide-frame {
  --theo-slide-deck-transition-duration: 250ms;
  position: absolute;
  inset: 0;
}

/* fade preset */
.theo-slide-deck-slide-frame[data-theo-slide-deck-transition="fade"]
  > [data-theo-slide-deck-slide-state="incoming"] {
  animation: theo-slide-deck-fade-in var(--theo-slide-deck-transition-duration) ease-out;
}

@keyframes theo-slide-deck-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* slide preset */
.theo-slide-deck-slide-frame[data-theo-slide-deck-transition="slide"][data-theo-slide-deck-direction="next"]
  > [data-theo-slide-deck-slide-state="incoming"] {
  animation: theo-slide-deck-slide-in-right var(--theo-slide-deck-transition-duration) ease-out;
}

.theo-slide-deck-slide-frame[data-theo-slide-deck-transition="slide"][data-theo-slide-deck-direction="prev"]
  > [data-theo-slide-deck-slide-state="incoming"] {
  animation: theo-slide-deck-slide-in-left var(--theo-slide-deck-transition-duration) ease-out;
}

@keyframes theo-slide-deck-slide-in-right {
  from {
    transform: translateX(30%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes theo-slide-deck-slide-in-left {
  from {
    transform: translateX(-30%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .theo-slide-deck-slide-frame,
  .theo-slide-deck-slide-frame * {
    animation-duration: 0ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0ms !important;
  }
}

/**
 * Hash routing hook (ADR D13).
 *
 * Pattern `#/N` (1-based). Bidirectional sync:
 *   - Initial state: read via `useDeckState`'s lazy `initFromHash` (D17 SSR-safe).
 *   - hashchange event → JUMP_TO.
 *   - currentIndex change → `history.replaceState` (does NOT trigger hashchange,
 *     so no infinite loop — verified in test EC-10).
 */
import { type Dispatch, useEffect } from "react";
import type { DeckAction } from "@/components/blocks/slide-deck/use-deck-state";

export interface UseDeckHashRoutingOptions {
  enabled?: boolean;
  totalSlides: number;
  currentIndex: number;
}

/** Read hash → return 0-based index, or undefined if not present/invalid. */
export function readHashIndex(hash: string): number | undefined {
  if (!hash || hash === "#" || hash === "#/") return undefined;
  const match = hash.match(/^#\/(\d+)/);
  if (!match) return undefined;
  const oneBased = Number.parseInt(match[1] ?? "", 10);
  if (!Number.isFinite(oneBased) || oneBased < 1) return undefined;
  return oneBased - 1;
}

/** SSR-safe wrapper for initial hash read (D17). */
export function readInitialHash(): number | undefined {
  if (typeof window === "undefined") return undefined;
  return readHashIndex(window.location.hash);
}

/** Format index → hash string. */
export function formatHash(zeroBasedIndex: number): string {
  return `#/${zeroBasedIndex + 1}`;
}

export function useDeckHashRouting(
  dispatch: Dispatch<DeckAction>,
  opts: UseDeckHashRoutingOptions,
): void {
  const { enabled = true, totalSlides, currentIndex } = opts;

  // Listen for hashchange (back/forward, manual edit, shared link click).
  useEffect(() => {
    if (!enabled) return;
    if (typeof window === "undefined") return;
    const handler = (): void => {
      const idx = readHashIndex(window.location.hash);
      if (typeof idx !== "number") return;
      const clamped = Math.max(0, Math.min(idx, Math.max(0, totalSlides - 1)));
      dispatch({ type: "JUMP_TO", index: clamped });
    };
    window.addEventListener("hashchange", handler);
    return () => window.removeEventListener("hashchange", handler);
  }, [enabled, totalSlides, dispatch]);

  // Sync currentIndex → hash via replaceState (silent, no hashchange fired).
  useEffect(() => {
    if (!enabled) return;
    if (typeof window === "undefined") return;
    const targetHash = formatHash(currentIndex);
    if (window.location.hash === targetHash) return;
    // replaceState does NOT trigger hashchange — verified in test EC-10.
    window.history.replaceState(null, "", targetHash);
  }, [enabled, currentIndex]);
}

/**
 * Keyboard navigation hook (ADR D9).
 *
 * Hardcoded bindings (no remap in v0.4):
 *   ArrowRight, Space, PageDown → NEXT_SLIDE
 *   ArrowLeft,  PageUp          → PREV_SLIDE
 *   Home                        → JUMP_TO 0
 *   End                         → JUMP_TO last
 *   Escape                      → SET_FULLSCREEN false
 *   f / F                       → toggleFullscreen callback
 *   n / N / p / P               → TOGGLE_PRESENTER
 *   Ctrl+P / Meta+P             → onPrint callback (preventDefault)
 *
 * Guards: ignora events quando target é INPUT, TEXTAREA, ou contentEditable
 * (consumer pode ter inputs em modais sem conflito).
 */
import { type Dispatch, useEffect } from "react";
import type { DeckAction } from "@/components/blocks/slide-deck/use-deck-state";

export interface UseDeckKeyboardOptions {
  enabled?: boolean;
  totalSlides: number;
  onToggleFullscreen?: () => void;
  onPrint?: () => void;
}

function isEditableTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  const tag = target.tagName;
  if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") return true;
  if (target.isContentEditable) return true;
  return false;
}

export function useDeckKeyboard(
  dispatch: Dispatch<DeckAction>,
  opts: UseDeckKeyboardOptions,
): void {
  const { enabled = true, totalSlides, onToggleFullscreen, onPrint } = opts;
  useEffect(() => {
    if (!enabled) return;
    const handler = (event: KeyboardEvent): void => {
      if (isEditableTarget(event.target)) return;

      const key = event.key;
      const isPrintCombo = (event.ctrlKey || event.metaKey) && (key === "p" || key === "P");

      if (isPrintCombo) {
        event.preventDefault();
        onPrint?.();
        return;
      }

      switch (key) {
        case "ArrowRight":
        case " ":
        case "Spacebar":
        case "PageDown":
          dispatch({ type: "NEXT_SLIDE" });
          break;
        case "ArrowLeft":
        case "PageUp":
          dispatch({ type: "PREV_SLIDE" });
          break;
        case "Home":
          dispatch({ type: "JUMP_TO", index: 0 });
          break;
        case "End":
          dispatch({ type: "JUMP_TO", index: Math.max(0, totalSlides - 1) });
          break;
        case "Escape":
          dispatch({ type: "SET_FULLSCREEN", value: false });
          break;
        case "f":
        case "F":
          onToggleFullscreen?.();
          break;
        case "n":
        case "N":
        case "p":
        case "P":
          dispatch({ type: "TOGGLE_PRESENTER" });
          break;
        default:
          return;
      }
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [enabled, totalSlides, dispatch, onToggleFullscreen, onPrint]);
}

/**
 * Deck state machine (ADR D5).
 *
 * Single useReducer governs all deck-level state transitions: currentIndex,
 * currentFragment, presenterMode, fullscreen, transitionDirection.
 *
 * NEXT_SLIDE advances fragment first if `currentFragment < totalFragmentsInCurrent`,
 * else advances slide. PREV_SLIDE mirrors. JUMP_TO clamps to valid range.
 *
 * ADR D17: lazy init reads hash via `initFromHash` callback when provided —
 * SSR-safe (callback guards `typeof window !== "undefined"`).
 */
import { type Dispatch, useReducer } from "react";

export interface DeckState {
  currentIndex: number;
  currentFragment: number;
  presenterMode: boolean;
  fullscreen: boolean;
  transitionDirection: "none" | "next" | "prev";
  totalSlides: number;
  totalFragmentsInCurrent: number;
}

export type DeckAction =
  | { type: "NEXT_SLIDE" }
  | { type: "PREV_SLIDE" }
  | { type: "JUMP_TO"; index: number }
  | { type: "NEXT_FRAGMENT" }
  | { type: "PREV_FRAGMENT" }
  | { type: "RESET_FRAGMENTS" }
  | { type: "TOGGLE_PRESENTER" }
  | { type: "SET_FULLSCREEN"; value: boolean }
  | { type: "UPDATE_TOTAL_SLIDES"; total: number }
  | { type: "UPDATE_TOTAL_FRAGMENTS"; total: number }
  | { type: "TRANSITION_END" };

export function deckReducer(state: DeckState, action: DeckAction): DeckState {
  switch (action.type) {
    case "NEXT_SLIDE": {
      // Advance fragment first when there are remaining fragments.
      if (state.currentFragment < state.totalFragmentsInCurrent) {
        return { ...state, currentFragment: state.currentFragment + 1 };
      }
      const next = Math.min(state.currentIndex + 1, Math.max(0, state.totalSlides - 1));
      if (next === state.currentIndex) return state;
      return {
        ...state,
        currentIndex: next,
        currentFragment: 0,
        transitionDirection: "next",
      };
    }
    case "PREV_SLIDE": {
      if (state.currentFragment > 0) {
        return { ...state, currentFragment: state.currentFragment - 1 };
      }
      const prev = Math.max(state.currentIndex - 1, 0);
      if (prev === state.currentIndex) return state;
      return {
        ...state,
        currentIndex: prev,
        currentFragment: 0,
        transitionDirection: "prev",
      };
    }
    case "JUMP_TO": {
      const clamped = Math.max(0, Math.min(action.index, Math.max(0, state.totalSlides - 1)));
      if (clamped === state.currentIndex) return state;
      return {
        ...state,
        currentIndex: clamped,
        currentFragment: 0,
        transitionDirection: "none",
      };
    }
    case "NEXT_FRAGMENT": {
      if (state.currentFragment >= state.totalFragmentsInCurrent) return state;
      return { ...state, currentFragment: state.currentFragment + 1 };
    }
    case "PREV_FRAGMENT": {
      if (state.currentFragment <= 0) return state;
      return { ...state, currentFragment: state.currentFragment - 1 };
    }
    case "RESET_FRAGMENTS":
      return { ...state, currentFragment: 0 };
    case "TOGGLE_PRESENTER":
      return { ...state, presenterMode: !state.presenterMode };
    case "SET_FULLSCREEN":
      return state.fullscreen === action.value ? state : { ...state, fullscreen: action.value };
    case "UPDATE_TOTAL_SLIDES": {
      const next = Math.max(0, action.total);
      const clampedIdx = Math.max(0, Math.min(state.currentIndex, Math.max(0, next - 1)));
      return { ...state, totalSlides: next, currentIndex: clampedIdx };
    }
    case "UPDATE_TOTAL_FRAGMENTS":
      return { ...state, totalFragmentsInCurrent: Math.max(0, action.total) };
    case "TRANSITION_END":
      return state.transitionDirection === "none"
        ? state
        : { ...state, transitionDirection: "none" };
  }
}

export interface UseDeckStateOptions {
  initialIndex?: number;
  totalSlides: number;
  /** Lazy initializer hook (D17): returns initial index, e.g. parsing hash. */
  initFromHash?: () => number | undefined;
}

function initDeckState(init: UseDeckStateOptions): DeckState {
  const total = Math.max(0, init.totalSlides);
  let idx = init.initialIndex ?? 0;
  if (init.initFromHash) {
    const fromHash = init.initFromHash();
    if (typeof fromHash === "number" && Number.isFinite(fromHash)) {
      idx = fromHash;
    }
  }
  const clamped = Math.max(0, Math.min(idx, Math.max(0, total - 1)));
  return {
    currentIndex: clamped,
    currentFragment: 0,
    presenterMode: false,
    fullscreen: false,
    transitionDirection: "none",
    totalSlides: total,
    totalFragmentsInCurrent: 0,
  };
}

export function useDeckState(
  opts: UseDeckStateOptions,
): readonly [DeckState, Dispatch<DeckAction>] {
  const [state, dispatch] = useReducer(deckReducer, opts, initDeckState);
  return [state, dispatch] as const;
}

/**
 * Touch swipe hook (ADR D10).
 *
 * Detecta swipe horizontal via Pointer Events nativos:
 *   - threshold: 50px de deslocamento
 *   - velocity: > 0.3 px/ms
 *   - direction guard: |dx| > 2*|dy| (bloqueia swipe vertical / scroll)
 *
 * Swipe left (dx < 0) → NEXT_SLIDE
 * Swipe right (dx > 0) → PREV_SLIDE
 *
 * EC-6: pointercancel limpa o tracking state (mobile browser pode cancelar mid-swipe).
 * EC-7: tracking limita ao primeiro pointerId (multi-touch é ignorado).
 */
import { type Dispatch, type RefObject, useEffect } from "react";
import type { DeckAction } from "@/components/blocks/slide-deck/use-deck-state";

export interface UseDeckSwipeOptions {
  enabled?: boolean;
}

interface TrackedPointer {
  pointerId: number;
  startX: number;
  startY: number;
  startedAt: number;
}

const SWIPE_THRESHOLD_PX = 50;
const SWIPE_VELOCITY_PX_PER_MS = 0.3;

export function useDeckSwipe(
  ref: RefObject<HTMLElement | null>,
  dispatch: Dispatch<DeckAction>,
  opts: UseDeckSwipeOptions = {},
): void {
  const { enabled = true } = opts;
  useEffect(() => {
    if (!enabled) return;
    const el = ref.current;
    if (!el) return;

    let tracked: TrackedPointer | null = null;

    const onPointerDown = (e: PointerEvent): void => {
      // EC-7: ignore secondary pointers (multi-touch).
      if (tracked !== null) return;
      tracked = {
        pointerId: e.pointerId,
        startX: e.clientX,
        startY: e.clientY,
        startedAt: e.timeStamp,
      };
    };

    const onPointerUp = (e: PointerEvent): void => {
      if (!tracked || e.pointerId !== tracked.pointerId) return;
      const dx = e.clientX - tracked.startX;
      const dy = e.clientY - tracked.startY;
      const dt = Math.max(1, e.timeStamp - tracked.startedAt);
      tracked = null;

      const absDx = Math.abs(dx);
      const absDy = Math.abs(dy);
      const velocity = absDx / dt;

      // Direction guard: horizontal-dominant swipe only.
      if (absDx < absDy * 2) return;
      // Threshold + velocity guard.
      if (absDx < SWIPE_THRESHOLD_PX) return;
      if (velocity < SWIPE_VELOCITY_PX_PER_MS) return;

      if (dx < 0) {
        dispatch({ type: "NEXT_SLIDE" });
      } else if (dx > 0) {
        dispatch({ type: "PREV_SLIDE" });
      }
    };

    const onPointerCancel = (e: PointerEvent): void => {
      // EC-6: clear tracking on cancel (browser back gesture, system interruption).
      if (tracked && e.pointerId === tracked.pointerId) {
        tracked = null;
      }
    };

    el.addEventListener("pointerdown", onPointerDown);
    el.addEventListener("pointerup", onPointerUp);
    el.addEventListener("pointercancel", onPointerCancel);
    return () => {
      el.removeEventListener("pointerdown", onPointerDown);
      el.removeEventListener("pointerup", onPointerUp);
      el.removeEventListener("pointercancel", onPointerCancel);
    };
  }, [enabled, ref, dispatch]);
}

/**
 * Cross-browser fullscreen hook (ADR D6 area / EC-8).
 *
 * Wraps `Element.requestFullscreen()` + Safari `webkit*` prefix. Listens
 * `fullscreenchange` (+ webkit) to sync state when user presses Esc via the
 * native UI.
 *
 * EC-8: iOS Safari < 16 doesn't expose fullscreen on arbitrary elements (only
 * `<video>`). Feature-detect — when unavailable, hook is a no-op and `toggle`
 * is safe to call.
 */
import { type RefObject, useCallback, useEffect, useState } from "react";

interface VendoredElement extends HTMLElement {
  webkitRequestFullscreen?: () => Promise<void>;
}

interface VendoredDocument extends Document {
  webkitFullscreenElement?: Element | null;
  webkitExitFullscreen?: () => Promise<void>;
}

function isFullscreenSupported(): boolean {
  if (typeof document === "undefined") return false;
  const doc = document as VendoredDocument;
  const el = document.documentElement as VendoredElement;
  return (
    Boolean(el.requestFullscreen ?? el.webkitRequestFullscreen) &&
    Boolean(doc.exitFullscreen ?? doc.webkitExitFullscreen)
  );
}

function currentFullscreenElement(): Element | null {
  if (typeof document === "undefined") return null;
  const doc = document as VendoredDocument;
  return document.fullscreenElement ?? doc.webkitFullscreenElement ?? null;
}

export interface UseFullscreenResult {
  isFullscreen: boolean;
  toggle: () => Promise<void>;
  isSupported: boolean;
}

export function useFullscreen(ref: RefObject<HTMLElement | null>): UseFullscreenResult {
  const supported = isFullscreenSupported();
  const [isFullscreen, setFullscreen] = useState(false);

  useEffect(() => {
    if (!supported) return;
    const handler = (): void => {
      setFullscreen(currentFullscreenElement() !== null);
    };
    document.addEventListener("fullscreenchange", handler);
    document.addEventListener("webkitfullscreenchange", handler);
    return () => {
      document.removeEventListener("fullscreenchange", handler);
      document.removeEventListener("webkitfullscreenchange", handler);
    };
  }, [supported]);

  const toggle = useCallback(async (): Promise<void> => {
    if (!supported) return;
    const el = ref.current as VendoredElement | null;
    if (!el) return;
    const doc = document as VendoredDocument;
    try {
      if (currentFullscreenElement()) {
        await (doc.exitFullscreen?.() ?? doc.webkitExitFullscreen?.());
      } else {
        await (el.requestFullscreen?.() ?? el.webkitRequestFullscreen?.());
      }
    } catch {
      // User denied or API unavailable — silent fallback. Defensive: never throw.
    }
  }, [ref, supported]);

  return { isFullscreen, toggle, isSupported: supported };
}

